// Shared helpers for the acceptance tests. Do NOT edit this file.
// The tests are black-box: they speak HTTP to your server at BASE_URL.

import { test } from 'bun:test'
import assert from 'node:assert/strict'
import {
  createHash,
  createHmac,
  createPublicKey,
  verify as cryptoVerify,
  randomBytes,
} from 'node:crypto'

export const BASE = (process.env.BASE_URL ?? 'http://localhost:3000').replace(/\/$/, '')
export const CLIENT_ID = 'demo-client'
export const REDIRECT_URI = 'http://localhost:4000/callback'
export const PASSWORD = 'correct-horse-battery-staple'
export const rnd = (n = 6) => randomBytes(n).toString('hex')
export const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms))

/**
 * Bonus test: skipped by default so it never blocks a milestone.
 * Run them with `bun run test:bonus` (sets BONUS=1).
 */
export const bonus = (name: string, fn: () => void | Promise<unknown>) =>
  (process.env.BONUS ? test : test.skip)(`[bônus] ${name}`, fn)

// biome-ignore lint/suspicious/noExplicitAny: response bodies are untyped on purpose
export type Json = any

export interface ReqOptions {
  json?: unknown
  form?: Record<string, string>
  raw?: string
  headers?: Record<string, string>
  bearer?: string
}

export interface Res {
  status: number
  headers: Headers
  text: string
  json: Json
  setCookies: string[]
}

/** A "browser": keeps cookies between requests. */
export class Session {
  cookies = new Map<string, string>()

  async req(method: string, path: string, opts: ReqOptions = {}): Promise<Res> {
    const { json, form, raw, headers = {}, bearer } = opts
    const h: Record<string, string> = { ...headers }
    let body: string | undefined
    if (json !== undefined) {
      h['content-type'] = 'application/json'
      body = JSON.stringify(json)
    } else if (form !== undefined) {
      h['content-type'] = 'application/x-www-form-urlencoded'
      body = new URLSearchParams(form).toString()
    } else if (raw !== undefined) {
      body = raw
    }
    if (bearer) h.authorization = `Bearer ${bearer}`
    if (this.cookies.size) {
      h.cookie = [...this.cookies].map(([k, v]) => `${k}=${v}`).join('; ')
    }
    let res: Response
    try {
      res = await fetch(BASE + path, { method, headers: h, body, redirect: 'manual' })
    } catch (err) {
      const e = err as { code?: string; message?: string }
      throw new Error(
        `Não consegui falar com ${BASE} (${e.code ?? e.message}). ` +
          'O seu servidor está rodando? Suba-o com `bun dev` e rode o teste de novo.',
      )
    }
    const setCookies = res.headers.getSetCookie?.() ?? []
    for (const sc of setCookies) {
      const [pair = '', ...attrs] = sc.split(';')
      const i = pair.indexOf('=')
      const name = pair.slice(0, i).trim()
      const value = pair.slice(i + 1).trim()
      const expired = attrs.some((a) => /^\s*max-age\s*=\s*0\s*$/i.test(a))
      if (value === '' || expired) this.cookies.delete(name)
      else this.cookies.set(name, value)
    }
    const text = await res.text()
    let data: Json
    try {
      data = text ? JSON.parse(text) : undefined
    } catch {
      data = undefined
    }
    return { status: res.status, headers: res.headers, text, json: data, setCookies }
  }

  get(path: string, opts?: ReqOptions) {
    return this.req('GET', path, opts)
  }
  post(path: string, json?: unknown, opts?: ReqOptions) {
    return this.req('POST', path, { ...opts, json })
  }
  put(path: string, json?: unknown, opts?: ReqOptions) {
    return this.req('PUT', path, { ...opts, json })
  }
  del(path: string, opts?: ReqOptions) {
    return this.req('DELETE', path, opts)
  }
}

export interface TestUser {
  email: string
  id: string
  s: Session
}

/** Registers a user, logs in and returns { email, id, s: Session }. */
export async function makeUser(prefix = 'user'): Promise<TestUser> {
  const email = `${prefix}-${rnd()}@example.test`
  const s = new Session()
  const r = await s.post('/register', { email, password: PASSWORD })
  assert.equal(r.status, 201, `register deveria dar 201, deu ${r.status}: ${r.text}`)
  const l = await s.post('/login', { email, password: PASSWORD })
  assert.equal(l.status, 200, `login deveria dar 200, deu ${l.status}: ${l.text}`)
  const me = await s.get('/me')
  assert.equal(me.status, 200, `/me deveria dar 200, deu ${me.status}`)
  return { email, id: me.json.id, s }
}

/** Fresh login (new session) for an existing user. */
export async function relogin(user: TestUser): Promise<TestUser> {
  const s = new Session()
  const l = await s.post('/login', { email: user.email, password: PASSWORD })
  assert.equal(l.status, 200)
  return { ...user, s }
}

// ---------- PKCE / OAuth ----------

export function pkce() {
  const verifier = randomBytes(32).toString('base64url') // 43 chars
  const challenge = createHash('sha256').update(verifier).digest('base64url')
  return { verifier, challenge }
}

/** Calls GET /authorize with the user's session. */
export async function authorize(
  session: Session,
  overrides: Record<string, string | undefined> = {},
) {
  const { verifier, challenge } = pkce()
  const merged: Record<string, string | undefined> = {
    response_type: 'code',
    client_id: CLIENT_ID,
    redirect_uri: REDIRECT_URI,
    scope: 'profile',
    state: rnd(),
    code_challenge: challenge,
    code_challenge_method: 'S256',
    ...overrides,
  }
  const params: Record<string, string> = {}
  for (const [k, v] of Object.entries(merged)) if (v !== undefined) params[k] = v
  const res = await session.get(`/authorize?${new URLSearchParams(params)}`)
  const location = res.headers.get('location')
  let loc: URL | undefined
  try {
    loc = location ? new URL(location, BASE) : undefined
  } catch {
    loc = undefined
  }
  return {
    res,
    loc,
    code: loc?.searchParams.get('code') ?? undefined,
    state: loc?.searchParams.get('state') ?? undefined,
    error: loc?.searchParams.get('error') ?? undefined,
    verifier,
    params,
  }
}

export function tokenRequest(session: Session, form: Record<string, string | undefined>) {
  const clean: Record<string, string> = { client_id: CLIENT_ID }
  for (const [k, v] of Object.entries(form)) if (v !== undefined) clean[k] = v
  return session.req('POST', '/token', { form: clean })
}

/** Full flow: authorize + code exchange. */
export async function getTokens(
  session: Session,
  { scope = 'profile', nonce }: { scope?: string; nonce?: string } = {},
) {
  const a = await authorize(session, { scope, nonce })
  assert.equal(a.res.status, 302, `/authorize deveria dar 302, deu ${a.res.status}: ${a.res.text}`)
  assert.ok(a.code, `Location sem "code": ${a.res.headers.get('location')}`)
  const t = await tokenRequest(session, {
    grant_type: 'authorization_code',
    code: a.code,
    redirect_uri: REDIRECT_URI,
    code_verifier: a.verifier,
  })
  assert.equal(t.status, 200, `/token deveria dar 200, deu ${t.status}: ${t.text}`)
  return { tokens: t.json, verifier: a.verifier, code: a.code, state: a.state }
}

// ---------- JWT ----------

export function decodeJwt(jwt: string) {
  const parts = jwt.split('.')
  assert.equal(parts.length, 3, 'JWT deve ter 3 partes')
  const [h, p, s] = parts as [string, string, string]
  return {
    header: JSON.parse(Buffer.from(h, 'base64url').toString()) as Json,
    payload: JSON.parse(Buffer.from(p, 'base64url').toString()) as Json,
    signingInput: `${h}.${p}`,
    signature: Buffer.from(s, 'base64url'),
  }
}

export function verifyJwtSignature(jwt: string, jwks: { keys: Json[] }) {
  const { header, signingInput, signature } = decodeJwt(jwt)
  const jwk = jwks.keys.find((k) => k.kid === header.kid)
  if (!jwk) return false
  const key = createPublicKey({ key: jwk, format: 'jwk' })
  const data = Buffer.from(signingInput)
  if (header.alg === 'RS256') return cryptoVerify('RSA-SHA256', data, key, signature)
  if (header.alg === 'ES256') {
    return cryptoVerify('sha256', data, { key, dsaEncoding: 'ieee-p1363' }, signature)
  }
  return false
}

// ---------- TOTP (RFC 6238, SHA-1, 6 digits, 30 s) ----------

function base32decode(s: string) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
  let bits = ''
  for (const c of s.replace(/=+$/, '').replace(/\s/g, '').toUpperCase()) {
    const i = alphabet.indexOf(c)
    assert.ok(i >= 0, `secret não está em base32: ${s}`)
    bits += i.toString(2).padStart(5, '0')
  }
  const bytes: number[] = []
  for (let i = 0; i + 8 <= bits.length; i += 8) bytes.push(Number.parseInt(bits.slice(i, i + 8), 2))
  return Buffer.from(bytes)
}

/** TOTP code for the current instant; stepOffset = -1, 0 or +1 windows of 30 s. */
export function totp(secret: string, stepOffset = 0, atMs = Date.now()) {
  const counter = Math.floor(atMs / 30000) + stepOffset
  const buf = Buffer.alloc(8)
  buf.writeBigUInt64BE(BigInt(counter))
  const h = createHmac('sha1', base32decode(secret)).update(buf).digest()
  const at = (i: number) => h[i] ?? 0
  const o = at(h.length - 1) & 0xf
  const code =
    ((at(o) & 0x7f) << 24) | ((at(o + 1) & 0xff) << 16) | ((at(o + 2) & 0xff) << 8) | at(o + 3)
  return String(code % 1_000_000).padStart(6, '0')
}
